// Read-only reconstruction of one recorded frame/cycle. No estimator changes.
#include "global_relocalization/raw_preprocessing.hpp"
#include "global_relocalization/raw_registration.hpp"
#include <pcl/common/transforms.h>
#include <pcl/io/pcd_io.h>
#include <pcl/kdtree/kdtree_flann.h>
#include <small_gicp/pcl/pcl_registration.hpp>
#include <small_gicp/pcl/pcl_point.hpp>
#include <small_gicp/util/downsampling_omp.hpp>
#include <nlohmann/json.hpp>
#include <fstream>
#include <filesystem>
#include <iostream>
using namespace global_relocalization;
using Json=nlohmann::json;
using CovCloud=pcl::PointCloud<pcl::PointCovariance>;
namespace fs=std::filesystem;
Json read(const fs::path&p){Json j;std::ifstream(p)>>j;return j;}
template<class M>Json matrix(const M&m){Json j=Json::array();for(int r=0;r<m.rows();++r){Json row=Json::array();for(int c=0;c<m.cols();++c)row.push_back(m(r,c));j.push_back(row);}return j;}
Eigen::Isometry3d rigid(const Json&j){Eigen::Isometry3d t;for(int r=0;r<4;++r)for(int c=0;c<4;++c)t.matrix()(r,c)=j[r][c];return t;}
Cloud::Ptr cloud(const Json&scan,const Json&p){Cloud raw,finite;if(pcl::io::loadPCDFile(scan.at("path").get<std::string>(),raw)<0)throw std::runtime_error("raw PCD unavailable");for(const auto&q:raw){Eigen::Vector3d x(q.x,q.y,q.z);if(x.allFinite()&&x.norm()>=p.at("min_range").get<double>()&&x.norm()<=p.at("max_range").get<double>())finite.push_back(q);}return deterministicVoxel(finite,p.at("leaf_size"));}
Eigen::Vector3d omega(const Json&rows,double stamp){size_t i=0;while(i<rows.size()&&rows[i][0].get<double>()<stamp)++i;if(i==rows.size()||i==0&&rows[i][0].get<double>()>stamp)throw std::runtime_error("no gyro bracket");auto w=[&](size_t k){return Eigen::Vector3d(rows[k][1],rows[k][2],rows[k][3]);};if(rows[i][0].get<double>()==stamp)return w(i);double a=rows[i-1][0],b=rows[i][0];return w(i-1)+(w(i)-w(i-1))*((stamp-a)/(b-a));}
Json features(const CovCloud&c){small_gicp::UnsafeKdTree<CovCloud> tree(c);Json rows=Json::array();for(size_t i=0;i<c.size();++i){size_t idx[20];double dd[20];size_t n=tree.knn_search(small_gicp::traits::point(c,i),20,idx,dd);Eigen::Vector4d sum=Eigen::Vector4d::Zero();Eigen::Matrix4d cross=Eigen::Matrix4d::Zero();Eigen::Vector3d lo=Eigen::Vector3d::Constant(1e9),hi=-lo;Json neighbors=Json::array();for(size_t k=0;k<n;++k){auto p=small_gicp::traits::point(c,idx[k]);sum+=p;cross+=p*p.transpose();lo=lo.cwiseMin(p.head<3>());hi=hi.cwiseMax(p.head<3>());neighbors.push_back(idx[k]);}Eigen::Matrix4d cov=(cross-(sum/n)*sum.transpose())/n;Eigen::SelfAdjointEigenSolver<Eigen::Matrix3d> eig;eig.computeDirect(cov.block<3,3>(0,0));rows.push_back({{"point",matrix(small_gicp::traits::point(c,i).head<3>())},{"covariance",matrix(small_gicp::traits::cov(c,i).block<3,3>(0,0))},{"neighbors",neighbors},{"radius_m",std::sqrt(dd[n-1])},{"extent_m",matrix((hi-lo).eval())},{"raw_eigenvalues",matrix(eig.eigenvalues())},{"raw_normal",matrix(eig.eigenvectors().col(0))}});}return rows;}
struct State {std::vector<small_gicp::GICPFactor> f;std::vector<Eigen::Matrix<double,6,6>> hs;std::vector<double> costs;Eigen::Matrix<double,6,6> h=Eigen::Matrix<double,6,6>::Zero();double e=0;};
template<class Tree>State state(const CovCloud&t,const CovCloud&s,const Tree&tree,const Eigen::Isometry3d&z,double corr){State out;out.f.resize(s.size());small_gicp::DistanceRejector reject;reject.max_dist_sq=corr*corr;for(size_t i=0;i<s.size();++i){Eigen::Matrix<double,6,6> h=Eigen::Matrix<double,6,6>::Zero();Eigen::Matrix<double,6,1>b=Eigen::Matrix<double,6,1>::Zero();double e=0;out.f[i].linearize(t,s,tree,z,i,reject,&h,&b,&e);out.h+=h;out.e+=e;out.hs.push_back(h);out.costs.push_back(e);}return out;}
Json quality(const Cloud&t,const Cloud&s,const Eigen::Isometry3d&z,double corr){pcl::KdTreeFLANN<pcl::PointXYZ> tree;tree.setInputCloud(t.makeShared());std::vector<int>idx(1);std::vector<float>d(1);size_t n=0;double sum=0;for(const auto&q:s){Eigen::Vector3d p=z*Eigen::Vector3d(q.x,q.y,q.z);if(tree.nearestKSearch(pcl::PointXYZ(p.x(),p.y(),p.z()),1,idx,d)>0&&d[0]<=corr*corr){++n;sum+=d[0];}}return{{"fitness",std::sqrt(sum/n)},{"inlier_ratio",double(n)/s.size()}};}
int main(int argc,char**argv){if(argc!=6){std::cerr<<"INPUT LOCAL_NATIVE_DIR STATION_ID FAILED_ORDINAL NEW_OUTPUT\n";return 2;}try{const fs::path input_path=argv[1],local=argv[2],out=argv[5];if(fs::exists(out))throw std::runtime_error("output exists");fs::create_directories(out);auto input=read(input_path);Json st;for(auto&s:input["stations"])if(s["id"]==argv[3])st=s;if(st.is_null())throw std::runtime_error("station missing");const auto poses=read(local/argv[3]/"poses.json");const size_t fail=std::stoul(argv[4]);if(poses.at(fail).at("accepted").get<bool>())throw std::runtime_error("specified frame is accepted");auto p=input["params"];const double leaf=p["leaf_size"],corr=p["max_correspondence"];const int scans=p["submap_scans"];auto previous=rigid(poses[fail-1]["reference_from_sensor"]);Cloud target_raw;for(size_t k=fail>scans?fail-scans:0;k<fail;++k){if(!poses[k]["accepted"].get<bool>())throw std::runtime_error("target history includes rejected frame");auto c=cloud(st["scans"][k],p);Cloud transformed;pcl::transformPointCloud(*c,transformed,(previous.inverse()*rigid(poses[k]["reference_from_sensor"])).matrix().cast<float>());target_raw+=transformed;}auto target=deterministicVoxel(target_raw,leaf);auto source=cloud(st["scans"][fail],p);auto t=small_gicp::voxelgrid_sampling_omp<Cloud,CovCloud>(*target,leaf,1);auto s=small_gicp::voxelgrid_sampling_omp<Cloud,CovCloud>(*source,leaf,1);small_gicp::estimate_covariances_omp(*t,20,1);small_gicp::estimate_covariances_omp(*s,20,1);small_gicp::KdTree<CovCloud> tree(t,small_gicp::KdTreeBuilderOMP(1));auto samples=read(input.at("imu_samples_json").get<std::string>());auto cal=read(local/"trusted_calibration.json");Eigen::Vector3d bias(cal["gyro_bias"][0],cal["gyro_bias"][1],cal["gyro_bias"][2]);const double start=poses[fail-1]["stamp"],end=poses[fail]["stamp"];double time=start;Eigen::Vector3d w=omega(samples,start)-bias;Eigen::Matrix3d delta=Eigen::Matrix3d::Identity();auto step=[&](double next,const Eigen::Vector3d&raw){auto nw=raw-bias;Eigen::Vector3d d=.5*(w+nw)*(next-time);if(d.norm()>1e-12)delta=delta*Eigen::AngleAxisd(d.norm(),d.normalized()).toRotationMatrix();time=next;w=nw;};for(auto&r:samples){double now=r[0];if(now>start&&now<end)step(now,Eigen::Vector3d(r[1],r[2],r[3]));}step(end,omega(samples,end));auto sensor_base=rigid(input["base_from_sensor"]).inverse();Eigen::Isometry3d guess=Eigen::Isometry3d::Identity();guess.linear()=delta;guess.translation()=sensor_base.translation()-delta*sensor_base.translation();RawRotationPrior rp;rp.enabled=true;rp.rotation=delta;rp.inverse_variance=1./std::pow(p["rotation_sigma_floor"].get<double>(),2);RawBaseTranslationPrior tp;tp.enabled=true;tp.sensor_base_translation=sensor_base.translation();tp.inverse_variance=1./std::pow(std::max(p["stationary_translation_sigma_floor"].get<double>(),p["max_base_linear_speed"].get<double>()*(end-start)/3),2);Eigen::Isometry3d z=guess,a,b;Json chosen;for(auto&row:poses[fail]["iteration_trace"]){if(row["attempt"]==1&&row["iteration"]==12&&row["inner"]==0){a=z;Eigen::Matrix<double,6,1>d;for(int k=0;k<6;++k)d[k]=row["increment"][k];b=z*small_gicp::se3_exp(d);chosen=row;}if(row["accepted"].get<bool>()){Eigen::Matrix<double,6,1>d;for(int k=0;k<6;++k)d[k]=row["increment"][k];z=z*small_gicp::se3_exp(d);}}if(chosen.is_null())throw std::runtime_error("stable cycle trace anchor missing");auto sa=state(*t,*s,tree,a,corr),sb=state(*t,*s,tree,b,corr);Json point_rows=Json::array();double fixed=0,same=0;for(size_t i=0;i<s->size();++i){const auto&fa=sa.f[i];const auto&fb=sb.f[i];double fixed_cost=fa.error(*t,*s,b),same_cost=0;fixed+=fixed_cost;if(fa.inlier()){Eigen::Vector3d q=small_gicp::traits::point(*t,fa.target_index).head<3>()-(b*small_gicp::traits::point(*s,i)).head<3>();Eigen::Matrix4d cov=small_gicp::traits::cov(*t,fa.target_index)+b.matrix()*small_gicp::traits::cov(*s,i)*b.matrix().transpose();same_cost=.5*q.transpose()*cov.block<3,3>(0,0).inverse()*q;}same+=same_cost;point_rows.push_back({{"source",i},{"active_a",fa.inlier()},{"active_b",fb.inlier()},{"target_a",fa.inlier()?Json(fa.target_index):Json(nullptr)},{"target_b",fb.inlier()?Json(fb.target_index):Json(nullptr)},{"cost_a",sa.costs[i]},{"fixed_factor_cost_b",fixed_cost},{"same_nn_new_W_cost_b",same_cost},{"fresh_cost_b",sb.costs[i]},{"H_trace_a",sa.hs[i].trace()},{"H_trace_b",sb.hs[i].trace()}});}Eigen::SelfAdjointEigenSolver<Eigen::Matrix<double,6,6>> info(sb.h);Json report={{"sensor_only",true},{"GT_query_used",false},{"target_source_rebuilt_from_recorded_accepted_history",true},{"history_frames",scans},{"source_points",s->size()},{"target_points",t->size()},{"source_quality_points",source->size()},{"guess",matrix(guess.matrix())},{"state_a",matrix(a.matrix())},{"state_b",matrix(b.matrix())},{"trace_anchor",chosen},{"fresh_a_total",sa.e+rp.cost(a)+tp.cost(a)},{"fixed_a_factor_b_total",fixed+rp.cost(b)+tp.cost(b)},{"same_nn_new_W_b_total",same+rp.cost(b)+tp.cost(b)},{"fresh_b_total",sb.e+rp.cost(b)+tp.cost(b)},{"H_b",matrix(sb.h)},{"information_ratio_b",info.eigenvalues().minCoeff()/info.eigenvalues().maxCoeff()},{"quality_a",quality(*target,*source,a,corr)},{"quality_b",quality(*target,*source,b,corr)},{"final_reconstructed_quality",quality(*target,*source,z,corr)},{"rotation_prior_weight",rp.inverse_variance},{"translation_prior_weight",tp.inverse_variance},{"points",point_rows}};std::ofstream(out/"factors.json")<<report.dump(2)<<'\n';std::ofstream(out/"source_features.json")<<features(*s).dump(2)<<'\n';std::ofstream(out/"target_features.json")<<features(*t).dump(2)<<'\n';pcl::io::savePCDFileBinary((out/"source_pre_features.pcd").string(),*source);pcl::io::savePCDFileBinary((out/"target_pre_features.pcd").string(),*target);std::cout<<"rebuilt freshA="<<report["fresh_a_total"]<<" fixedB="<<report["fixed_a_factor_b_total"]<<" freshB="<<report["fresh_b_total"]<<" infoB="<<report["information_ratio_b"]<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
